pub fn rotate(a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }

    let k = offset % n; // normalize the rotation
    let mut b = Vec::with_capacity(n);

    // b[i] = a[(i + k) % n], implemented without `%` inside the loop.
    for i in 0..n {
        let mut j = i + k;
        if j >= n {
            j -= n;
        }
        b.push(a[j]);
    }

    b
}

